calculation = read("case-06/calculation.json")
record = read("case-06/record.json")
target = {
    "length": contract["length"], "points": contract["points"],
    "left": "dirichlet", "right": "dirichlet",
}
assert contract["equation"] == "-u_dd(x)=lambda*u(x)"
assert contract["boundary"] == {"left": "u(0)=0", "right": "u(1)=0"}
assert contract["modes"] == [0, 1, 2]
assert calculation["current_state"] == target

