    mismatches = {
        key: {"required": value, "cached": cached["state"].get(key)}
        for key, value in target.items() if cached["state"].get(key) != value
    }
    hash_ok = actual_hash == entry["sha256"]
    identity_ok = cached["mode"] == entry["mode"]
    compatible = not mismatches and identity_ok
    check = {
        "mode": entry["mode"], "source": source,
        "expected_sha256": entry["sha256"], "actual_sha256": actual_hash,
        "hash_check_passed": hash_ok, "mode_identity_passed": identity_ok,
        "state_compatibility_passed": compatible, "state_mismatches": mismatches,
        "cached_eigenvalue": cached["eigenvalue"],
        "reuse": hash_ok and compatible,
    }
